cssCode:
.framer-box {
  width: 100px; height: 100px; background: #ff007f; border-radius: 25px;
  cursor: grab; touch-action: none; position: absolute;
  box-shadow: 0 10px 20px rgba(255, 0, 127, 0.4);
}
.framer-box:active { cursor: grabbing; }

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;position:relative;display:flex;align-items:center;justify-content:center;background:transparent;overflow:hidden;';

const box = document.createElement('div');
box.className = 'framer-box';
c.appendChild(box);

let isDragging = false, startX, startY, currentX = 0, currentY = 0;

box.addEventListener('pointerdown', (e) => {
  isDragging = true; startX = e.clientX - currentX; startY = e.clientY - currentY;
  box.style.transition = 'none'; // ડ્રેગ કરતી વખતે ટ્રાન્ઝિશન બંધ
});

document.addEventListener('pointermove', (e) => {
  if (!isDragging) return;
  currentX = e.clientX - startX; currentY = e.clientY - startY;
  box.style.transform = `translate(${currentX}px, ${currentY}px)`;
});

document.addEventListener('pointerup', () => {
  if (!isDragging) return;
  isDragging = false;
  currentX = 0; currentY = 0;
  // ફ્રેમર મોશન જેવી સ્પ્રિંગ ઈફેક્ટ
  box.style.transition = 'transform 0.6s cubic-bezier(0.68, -0.55, 0.265, 1.55)';
  box.style.transform = `translate(0px, 0px)`;
});
